253	/**
254	 * The sheet's pools: each a name, at most once on the sheet, and its members, each a person on the
255	 * sheet at most once per pool with a share percent (two decimals, above 0.00 and at most 100.00).
256	 * A pool's total adds up its members' shares, a retired member's (one with a retirement date set,
257	 * whatever the date) counting as 0.00; the pool is balanced when the total is exactly 100.00.
258	 * <p>
259	 * With a pot set on the sheet, each member of a balanced pool has a cut: the pot times their share
260	 * divided by 100, rounded half to even to two decimals, a retired member's 0.00. The remainder, the
261	 * pot less the cuts added up, goes to the member with the largest share (the earliest added on a
262	 * tie), so the cuts total exactly the pot. An unbalanced pool, or no pot, has no cuts.
263	 * <p>
264	 * A person with a hold in force on the sheet's today (one whose dates include today) has a cut of
265	 * 0.00 in every pool, and their share is spread over the members left with a cut: each of those
266	 * cuts the pot times their share divided by the shares of the members with a cut added up, half to
267	 * even, the remainder as above (all 0.00 when no member is left with a cut). The pool's total share
268	 * and balance are unchanged by a hold.
269	 * <p>
270	 * A member may instead be another pool, with a share like a person's. A pool is a member of at most
271	 * one pool, never contains itself through any chain, and a chain of pools is at most three deep. A
272	 * pool that is a member of another has no pot of its own: its pot is its cut in the pool above (so
273	 * an unbalanced pool above, or none, leaves it with no cuts). The sheet's pot is the pot of a pool
274	 * that is a member of none.
275	 */
276	@Service
277	public class PoolService {
278	
279	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
280	
281	    /** The most pools in a chain, each a member of the one before. */
282	    private static final int MAX_DEPTH = 3;
283	
284	    /**
285	     * A member as listed: the person's id (0 for a pool), the member pool's name (null for a person),
286	     * the current name, their share, whether they are retired, and their cut of the pool's pot (two
287	     * decimals; blank when the pool is unbalanced or has no pot).
288	     */
289	    public record MemberView(long personId, String pool, String name, String share, boolean retired, String cut) {
290	    }
291	
292	    /** A pool as listed: its members in the order they were added, their total share (two decimals) and balance. */
293	    public record PoolView(long id, String name, List<MemberView> members, String totalShare, boolean balanced) {
294	    }
295	
296	    private final PoolRepository pools;
297	    private final PoolMemberRepository members;
298	    private final PersonRepository people;
299	    private final SheetService sheets;
300	    private final SheetRepository sheetRows;
301	    private final Audit audit;
302	    private final RoleService roles;
303	
304	    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
305	            SheetService sheets, SheetRepository sheetRows, Audit audit, RoleService roles) {
306	        this.pools = pools;
307	        this.members = members;
308	        this.people = people;
309	        this.sheets = sheets;
310	        this.sheetRows = sheetRows;
311	        this.audit = audit;
312	        this.roles = roles;
313	    }
