315	    @Transactional(readOnly = true)
316	    public List<PoolView> list(String sheetId) {
317	        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
318	        if (all.isEmpty()) {
319	            return List.of();
320	        }
321	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
322	                .collect(Collectors.toMap(Person::getId, Function.identity()));
323	        Map<Long, Pool> poolsById = all.stream().collect(Collectors.toMap(Pool::getId, Function.identity()));
324	        Map<Long, List<PoolMember>> byPool = members
325	                .findByPoolIdInOrderByIdAsc(poolsById.keySet()).stream()
326	                .collect(Collectors.groupingBy(PoolMember::getPoolId));
327	        var sheet = sheetRows.findById(sheetId);
328	        BigDecimal pot = sheet.map(s -> s.getPot()).orElse(null);
329	        LocalDate today = sheet.map(s -> s.getToday()).orElse(null);
330	        Map<Long, Shares> shares = new LinkedHashMap<>();
331	        Map<Long, Long> parentOf = new HashMap<>();
332	        for (Pool pool : all) {
333	            shares.put(pool.getId(), shares(pool, byPool.getOrDefault(pool.getId(), List.of()), byId, poolsById, today));
334	            for (PoolMember m : byPool.getOrDefault(pool.getId(), List.of())) {
335	                if (m.getMemberPoolId() != null) {
336	                    parentOf.put(m.getMemberPoolId(), pool.getId());
337	                }
338	            }
339	        }
340	        Map<Long, List<BigDecimal>> cuts = new HashMap<>();
341	        List<PoolView> out = new ArrayList<>();
342	        for (Pool pool : all) {
343	            Shares sh = shares.get(pool.getId());
344	            List<BigDecimal> poolCuts = cutsOf(pool.getId(), shares, parentOf, pot, cuts, new HashSet<>());
345	            List<MemberView> views = new ArrayList<>();
346	            for (int i = 0; i < sh.listed().size(); i++) {
347	                Listed l = sh.listed().get(i);
348	                views.add(new MemberView(l.personId(), l.pool(), l.name(), sh.shares().get(i).toPlainString(),
349	                        l.retired(), poolCuts == null ? "" : poolCuts.get(i).toPlainString()));
350	            }
351	            out.add(new PoolView(pool.getId(), pool.getName(), views, sh.total().toPlainString(), sh.balanced()));
352	        }
353	        return out;
354	    }
355	
356	    /**
357	     * A member as worked out: a person (with their id) or a pool (its id and name; the person id 0),
358	     * and whether a hold is in force on the sheet's today.
359	     */
360	    private record Listed(long personId, Long memberPoolId, String pool, String name, boolean retired,
361	            boolean held) {
362	    }
363	
364	    /** A pool's listed members, their shares, the total of the live ones and whether that is 100.00. */
365	    private record Shares(List<Listed> listed, List<BigDecimal> shares, BigDecimal total, boolean balanced) {
366	    }
367	
368	    private static Shares shares(Pool pool, List<PoolMember> poolMembers, Map<Long, Person> byId,
369	            Map<Long, Pool> poolsById, LocalDate today) {
370	        List<Listed> listed = new ArrayList<>();
371	        List<BigDecimal> shares = new ArrayList<>();
372	        BigDecimal total = BigDecimal.ZERO.setScale(2);
373	        for (PoolMember m : poolMembers) {
374	            Listed l;
375	            if (m.getMemberPoolId() != null) {
376	                Pool member = poolsById.get(m.getMemberPoolId());
377	                if (member == null) {
378	                    continue;
379	                }
380	                l = new Listed(0, member.getId(), member.getName(), member.getName(), false, false);
381	            } else {
382	                Person p = byId.get(m.getPersonId());
383	                if (p == null) {
384	                    continue;
385	                }
386	                l = new Listed(p.getId(), null, null, p.getName(), p.isRetired(),
387	                        today != null && p.heldOn(today));
388	            }
389	            BigDecimal share = m.getShare().setScale(2);
390	            listed.add(l);
391	            shares.add(share);
392	            if (!l.retired()) {
393	                total = total.add(share);
394	            }
395	        }
396	        return new Shares(listed, shares, total, total.compareTo(HUNDRED) == 0);
397	    }
398	
399	    /**
400	     * A pool's cuts, in its members' order, or null for none: a pool that is a member of another cuts
401	     * its cut in that pool, one that is a member of none the sheet's pot; an unbalanced pool, or no pot
402	     * to cut, has none.
403	     */
404	    private static List<BigDecimal> cutsOf(long poolId, Map<Long, Shares> shares, Map<Long, Long> parentOf,
405	            BigDecimal sheetPot, Map<Long, List<BigDecimal>> memo, Set<Long> visiting) {
406	        if (memo.containsKey(poolId)) {
407	            return memo.get(poolId);
408	        }
409	        Shares sh = shares.get(poolId);
410	        BigDecimal pot = sheetPot;
411	        Long parent = parentOf.get(poolId);
412	        if (parent != null) {
413	            pot = null;
414	            if (visiting.add(poolId)) {
415	                List<BigDecimal> above = cutsOf(parent, shares, parentOf, sheetPot, memo, visiting);
416	                if (above != null) {
417	                    List<Listed> siblings = shares.get(parent).listed();
418	                    for (int i = 0; i < siblings.size(); i++) {
419	                        if (Long.valueOf(poolId).equals(siblings.get(i).memberPoolId())) {
420	                            pot = above.get(i);
421	                        }
422	                    }
423	                }
424	            }
425	        }
426	        List<BigDecimal> cuts = sh.balanced() && pot != null ? cuts(pot, sh.listed(), sh.shares()) : null;
427	        memo.put(poolId, cuts);
428	        return cuts;
429	    }
430	    /**
431	     * Each member's cut of the pot, in the members' order: the pot times their share over the shares of
432	     * the members with a cut added up, half to even, a retired or held member's 0.00; the remainder to
433	     * the member with a cut with the largest share, the earliest on a tie.
434	     */
435	    private static List<BigDecimal> cuts(BigDecimal pot, List<Listed> listed, List<BigDecimal> shares) {
436	        BigDecimal cutShares = BigDecimal.ZERO.setScale(2);
437	        for (int i = 0; i < listed.size(); i++) {
438	            if (hasCut(listed.get(i))) {
439	                cutShares = cutShares.add(shares.get(i));
440	            }
441	        }
442	        List<BigDecimal> cuts = new ArrayList<>();
443	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
444	        int largest = -1;
445	        for (int i = 0; i < listed.size(); i++) {
446	            BigDecimal cut = BigDecimal.ZERO.setScale(2);
447	            if (hasCut(listed.get(i))) {
448	                cut = pot.multiply(shares.get(i)).divide(cutShares, 2, RoundingMode.HALF_EVEN);
449	                if (largest < 0 || shares.get(i).compareTo(shares.get(largest)) > 0) {
450	                    largest = i;
451	                }
452	            }
453	            cuts.add(cut);
454	            sum = sum.add(cut);
455	        }
456	        if (largest >= 0) {
457	            cuts.set(largest, cuts.get(largest).add(pot.subtract(sum)));
458	        }
459	        return cuts;
460	    }
461	
462	    /** Whether a member takes a cut: neither retired nor on a hold in force today. */
463	    private static boolean hasCut(Listed l) {
464	        return !l.retired() && !l.held();
465	    }
