467	    /** Add a pool (trimmed); a blank name is refused (422), one already on the sheet (409). */
468	    @Transactional
469	    public void add(String sheetId, String user, String name) {
470	        roles.refuseViewer(sheetId, user);
471	        sheets.load(sheetId, user);
472	        String text = name == null ? "" : name.trim();
473	        if (text.isEmpty()) {
474	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "Enter a pool name.");
475	        }
476	        // hold the sheet so the same name added twice at the same moment is checked one after the other
477	        sheetRows.findLockedById(sheetId);
478	        if (pools.existsBySheetIdAndName(sheetId, text)) {
479	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already on the sheet.");
480	        }
481	        try {
482	            pools.saveAndFlush(new Pool(sheetId, text));
483	        } catch (DataIntegrityViolationException e) {
484	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already on the sheet.");
485	        }
486	        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + text);
487	    }
