489	    /**
490	     * Add a person to a pool with a share: refused (422) for a share that is not a number of at most
491	     * two decimals above 0.00 and at most 100.00, (409) for a person already in the pool.
492	     */
493	    @Transactional
494	    public void addMember(String sheetId, String user, long poolId, long personId, String share) {
495	        roles.refuseViewer(sheetId, user);
496	        sheets.load(sheetId, user);
497	        BigDecimal pct = share(share);
498	        sheetRows.findLockedById(sheetId);
499	        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
500	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
501	        Person person = people.findByIdAndSheetId(personId, sheetId)
502	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "Choose a person."));
503	        if (members.existsByPoolIdAndPersonId(pool.getId(), person.getId())) {
504	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool.");
505	        }
506	        try {
507	            members.saveAndFlush(new PoolMember(sheetId, pool.getId(), person.getId(), pct));
508	        } catch (DataIntegrityViolationException e) {
509	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool.");
510	        }
511	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
512	                + " name=" + person.getName() + " share=" + pct.toPlainString());
513	    }
514	
515	    /**
516	     * Add another pool to a pool with a share, refused (422) for a share as for a person; (409) for a
517	     * pool already a member of a pool, for the pool itself or one that contains it through any chain,
518	     * and for a chain of pools that would be more than three deep.
519	     */
520	    @Transactional
521	    public void addPoolMember(String sheetId, String user, long poolId, long memberPoolId, String share) {
522	        roles.refuseViewer(sheetId, user);
523	        sheets.load(sheetId, user);
524	        BigDecimal pct = share(share);
525	        sheetRows.findLockedById(sheetId);
526	        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
527	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
528	        Pool member = pools.findByIdAndSheetId(memberPoolId, sheetId)
529	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "Choose a member."));
530	        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
531	        Map<Long, Long> parentOf = new HashMap<>();
532	        Map<Long, List<Long>> childrenOf = new HashMap<>();
533	        for (PoolMember m : members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList())) {
534	            if (m.getMemberPoolId() != null) {
535	                parentOf.put(m.getMemberPoolId(), m.getPoolId());
536	                childrenOf.computeIfAbsent(m.getPoolId(), k -> new ArrayList<>()).add(m.getMemberPoolId());
537	            }
538	        }
539	        if (parentOf.containsKey(member.getId())) {
540	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already a member of a pool.");
541	        }
542	        // the pool and the pools above it: the member may be none of them
543	        int above = 0;
544	        for (Long at = pool.getId(); at != null && above <= all.size(); at = parentOf.get(at)) {
545	            if (at.equals(member.getId())) {
546	                throw new ResponseStatusException(HttpStatus.CONFLICT, "A pool cannot contain itself.");
547	            }
548	            above++;
549	        }
550	        if (above + height(member.getId(), childrenOf, 0) > MAX_DEPTH) {
551	            throw new ResponseStatusException(HttpStatus.CONFLICT,
552	                    "A chain of pools is at most " + MAX_DEPTH + " deep.");
553	        }
554	        try {
555	            members.saveAndFlush(PoolMember.ofPool(sheetId, pool.getId(), member.getId(), pct));
556	        } catch (DataIntegrityViolationException e) {
557	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already a member of a pool.");
558	        }
559	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
560	                + " name=" + member.getName() + " share=" + pct.toPlainString());
561	    }
