563	    /** How many levels of pools a pool heads: 1 for one with no pool members. */
564	    private static int height(Long poolId, Map<Long, List<Long>> childrenOf, int seen) {
565	        int most = 0;
566	        if (seen <= MAX_DEPTH) {
567	            for (Long child : childrenOf.getOrDefault(poolId, List.of())) {
568	                most = Math.max(most, height(child, childrenOf, seen + 1));
569	            }
570	        }
571	        return 1 + most;
572	    }
573	
574	    private static BigDecimal share(String text) {
575	        String s = text == null ? "" : text.trim();
576	        if (!s.matches("\\d{1,3}(\\.\\d{1,2})?")) {
